public class GunFixture {public static final GunFixture ITEM=new GunFixture();public void unloadAttachment(Object access,ItemStack s,Object type){s.laser="";}public boolean allowAttachment(ItemStack s,ItemStack a){return true;}public void installAttachment(Object access,ItemStack s,ItemStack a){s.laser=a.components.get("attachment").toString();}public Object getAttachmentId(ItemStack s,Object type){return s.laser;}public void setLaserColor(ItemStack s,int color){s.components.put("laserColor",color);}public Object getGunId(ItemStack s){return s.gunId;}public int getCurrentAmmoCount(ItemStack s){return s.ammo;}public void setCurrentAmmoCount(ItemStack s,int n){s.ammo=n;}public void setBulletInBarrel(ItemStack s,boolean b){}public static class Data{public int getAmmoAmount(){return 30;}}}
